<?php $pageTitle='Customize Product'; require 'includes/header.php'; $id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.is_archived=0');$stmt->execute([$id]);$p=$stmt->fetch(); if(!$p) die('Product not found');
if($_SERVER['REQUEST_METHOD']==='POST'){ $key=uniqid('cart_',true); $_SESSION['cart'][$key]=['product_id'=>$id,'qty'=>max(1,(int)$_POST['qty']),'notes'=>trim($_POST['notes']??'')]; $_SESSION['flash']='Product added to cart. Uploads can also be attached during checkout.'; redirect('cart.php'); } ?>
<main class="section-pad"><div class="container"><div class="row g-5"><div class="col-lg-6"><img src="<?= e($p['image'] ?: 'assets/images/product-placeholder.svg') ?>" class="img-fluid rounded-4 shadow" alt="<?= e($p['name']) ?>"></div><div class="col-lg-6"><span class="badge badge-brand mb-2"><?= e($p['category_name']) ?></span><h1 class="fw-bold"><?= e($p['name']) ?></h1><p class="lead"><?= e($p['description']) ?></p><h3 class="text-danger fw-bold"><?= money($p['price']) ?></h3><p>Available stock: <b><?= (int)$p['stock'] ?></b></p><form method="post" enctype="multipart/form-data" class="mt-4"><label class="form-label">Upload design/file option</label><input class="form-control mb-3" type="file" disabled><div class="form-text mb-3">Final design files are uploaded on checkout so they are connected to your order.</div><label class="form-label">Quantity</label><input name="qty" type="number" min="1" max="<?= (int)$p['stock'] ?>" value="1" class="form-control mb-3" required><label class="form-label">Custom notes/instructions</label><textarea name="notes" class="form-control mb-3" rows="4" placeholder="Example: size, color, deadline, print placement"></textarea><button class="btn btn-red btn-lg">Add to Cart</button></form></div></div></div></main><?php require 'includes/footer.php'; ?>